package main
import("testing";"strings";"net/http";"net/http/httptest")
func sampleWifiProfiles()map[string]wifiProfile{return map[string]wifiProfile{"rt_":{"ssid":"MIFI","auth_mode":"psk","crypto":"aes","wpa_psk":"test-pass24","wpa_mode":"2","radio_x":"1"},"wl_":{"ssid":"MIFI_5G","auth_mode":"psk","crypto":"aes","wpa_psk":"test-pass5G","wpa_mode":"2","radio_x":"0"}}}
func TestWifiUnifyPreservesOriginal(t *testing.T){original:=sampleWifiProfiles();merged:=unifiedWifiProfiles(original);if !wifiIsUnified(merged){t.Fatal("not unified")};if original["wl_"]["ssid"]!="MIFI_5G"||original["wl_"]["radio_x"]!="0"||original["wl_"]["wpa_psk"]!="test-pass5G"{t.Fatal("original backup mutated")};if merged["wl_"]["wpa_psk"]!=original["rt_"]["wpa_psk"]{t.Fatal("password not synchronized")};merged["wl_"]["ssid"]="different";if wifiIsUnified(merged){t.Fatal("mismatch accepted")}}
func TestWifiProfileValidation(t *testing.T){p:=sampleWifiProfiles()["rt_"];p["auth_mode"]="open";if validWifiProfile(p){t.Fatal("insecure profile accepted")};p["auth_mode"]="psk";p["wpa_psk"]="short";if validWifiProfile(p){t.Fatal("short password accepted")};p["wpa_psk"]="test-pass24";p["ssid"]=strings.Repeat("字",11);if validWifiProfile(p){t.Fatal("overlong UTF8 SSID accepted")}}
func wifiForm(prefix,sid string)string{s:=`<input name="action_script" value="restart_wifis"><input name="sid_list" value="`+sid+`">`;for _,key:=range wifiProfileFields{s+=`<input name="`+prefix+key+`">`};return s}
func TestWifiApplyBothBands(t *testing.T){p:=unifiedWifiProfiles(sampleWifiProfiles());v,e:=wifiApplyValues(p,wifiForm("rt_","WLANConfig11b;"),wifiForm("wl_","WLANConfig11a;"));if e!=nil{t.Fatal(e)};if v.Get("sid_list")!="WLANConfig11b;WLANConfig11a;"||v.Get("wl_ssid")!="MIFI"||v.Get("rt_ssid")!="MIFI"||v.Get("action_script")!="restart_wifis"{t.Fatal("incorrect atomic form")};if _,e=wifiApplyValues(p,"",wifiForm("wl_","WLANConfig11a;"));e==nil{t.Fatal("unknown firmware accepted")}}
func TestWifiUnifyStatusDoesNotExposePassword(t *testing.T){old:=demo;demo=true;defer func(){demo=old}();w:=httptest.NewRecorder();wifiUnifyAPI(w,httptest.NewRequest(http.MethodGet,"/api/wifi/unify",nil));if w.Code!=200{t.Fatal(w.Code)};if strings.Contains(w.Body.String(),"preview-only")||strings.Contains(w.Body.String(),"wpa_psk"){t.Fatal("credentials exposed")}}
